-- Idempotent: stable codes/slugs are used for all upserts; existing unrelated rows are not deleted.

alter table public.regions add column if not exists region_level text not null default 'governorate';
alter table public.regions add column if not exists name_ar_normalized text;
alter table public.regions add column if not exists name_en_normalized text;
alter table public.regions drop constraint if exists regions_region_level_check;
alter table public.regions add constraint regions_region_level_check check (region_level in ('governorate', 'district'));
create index if not exists regions_parent_active_idx on public.regions(parent_region_id, is_active, name_ar);
create index if not exists regions_level_active_idx on public.regions(region_level, is_active, name_ar);


